mzEffectSizesBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "mzEffectSizesBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "Metafora",
                name = "mzEffectSizes",
                version = c(1,0,0),
                options = options,
                results = mzEffectSizesResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'none')
        }))

#' Generic Effect Sizes
#'
#' 
#' @param d3ExportForest .
