#' @param slab .
#' @param yi .
#' @param vi .
#' @param ciLower .
#' @param ciUpper .
#' @param inputCiLevel .
#' @param subgroup .
#' @param moderator .
#' @param robDomains .
#' @param tabbedControl .
#' @param tabbedControlModelType .
#' @param modelest .
#' @param testType .
#' @param level .
#' @param modelmea .
#' @param meaType .
#' @param showBackTransform .
#' @param showHetTest .
#' @param hetTestBoot .
#' @param showHEC .
#' @param showModelFit .
#' @param showTextRepo .
#' @param addfit .
#' @param addpred .
#' @param forestPredictionStyle .
#' @param showweights .
#' @param shadeRows .
#' @param pchForest .
#' @param mainTitle .
#' @param forestOrder .
