#' @param infDiagPlotShow .
#' @param infQQPlotShow .
#' @param lhPlotShow .
#' @param tostLower .
#' @param tostUpper .
#' @param tostAlpha .
#' @param showTost .
#' @param tostPlotShow .
#' @param scatterPlotShow .
#' @param scatterPlotLegend .
#' @param scatterPlotLabel .
#' @param scatterPlotGrid .
#' @param scatterPlotPI .
#' @param scatterPlotCI .
#' @param scatterPlotScale .
#' @param radialPlotShow .
#' @param radialPlotCenter .
#' @param radialPlotTransf .
#' @param radialPlotSteps .
#' @param baujatPlotShow .
#' @param baujatPlotSymbol .
#' @param baujatPlotGrid .
#' @param goshPlotShow .
#' @param goshPlotHet .
#' @param goshPlotSubsets .
#' @param goshPlotOut .
#' @param leave1outPlotMode .
#' @param leave1outPlotShow .
#' @param leave1outTableShow .
#' @param leave1outPrediction .
#' @param leave1outShade .
#' @param leave1outMode .
#' @param leave1outGroupOrder .
#' @param leave1outOrder .
#' @param distabPBA .
#' @param showTes .
#' @param pcurvePlotShow .
#' @param fsntype .
#' @param tesAlternative .
#' @param tesH0 .
#' @param tesTest .
#' @param tesAlpha .
#' @param showSelmodel .
#' @param selModelType .
#' @param showPuniform .
#' @param alphaPunif .
#' @param methodPunif .
#' @param puniformSide .
#' @param jlogMode .
#' @param cumulativeTableShow .
#' @param cumulativePlotMode .
#' @param cumulativeOrder .
#' @param cumulativeGroupOrder .
#' @param cumulativeDirection .
#' @param cumulativeSortVariable .
#' @param cumulativePrediction .
#' @param cumulativeShade .
#' @param predProbTableShow .
#' @param predProbPlotShow .
#' @param predProbThreshold .
#' @param predProbDirection .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$d3SessionScope} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$toastTrigger} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$debugLog} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$textRICH} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$tableTauSqaured} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$subgroupResults} \tab \tab \tab \tab \tab Results by subgroup levels \cr
#'   \code{results$hetTestTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$heterogeneityComparison} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$modelFitRICH} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$OutputHtml} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$mzForestPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$outD3ForestPlot} \tab \tab \tab \tab \tab a svg \cr
#'   \code{results$outD3ForestPlotExport} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$outHtmlTable} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$mzFunnelPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$outD3FunnelPlot} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$outD3FunnelPlotExport} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$mzInfDiagPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$mzInfQQPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$mzLhPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$mzScatterPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$mzRadialPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$mzBaujatPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$mzGoshPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$mzTostPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$outHtmlTost} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$cumulativePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$outD3CumulativePlot} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$outD3CumulativePlotExport} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$cumulativeTable} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$leave1outClassicPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$outD3Leave1OutPlot} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$outD3Leave1OutPlotExport} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$outHtmlLeave1Out} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$tabPubBias} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$outHtmlSelmodel} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$outHtmlTes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$outHtmlPuniform} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$mzPcurvePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$effectsizeOV} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$stderrorOV} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$varianceOV} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$predProbTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$mzPredProbPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$textRICH$asDF}
#'
#' \code{as.data.frame(results$textRICH)}
#'
#' @export
mzEffectSizes <- function(
    d3ExportForest = "",
    d3ExportFunnel = "",
    d3ExportLeave1Out = "",
    d3ExportCumulative = "",
    data,
    slab,
    yi,
    vi,
    ciLower,
    ciUpper,
    inputCiLevel = 95,
    subgroup,
    moderator,
    robDomains,
    tabbedControl = FALSE,
    tabbedControlModelType = "effectsize",
    modelest = "REML",
    testType = "z",
    level = 95,
    modelmea = "GEN",
    meaType = "vimt",
    showBackTransform = FALSE,
    showHetTest = FALSE,
    hetTestBoot = 1000,
    showHEC = FALSE,
    showModelFit = FALSE,
    showTextRepo = FALSE,
    addfit = TRUE,
    addpred = FALSE,
    forestPredictionStyle = "line2",
    showweights = FALSE,
    shadeRows = FALSE,
    pchForest = "bSquare",
    mainTitle,
    forestOrder = "fit",
    xAxisTitle,
    ordSubgr = FALSE,
    steps = 5,
    forestPlotMode = "posOff",
    forestPlotWidth = 600,
    forestPlotHeight = 600,
    forestTableShow = FALSE,
    forestRobShow = FALSE,
    yaxis = "sei",
    yaxisInv = FALSE,
    enhanceFunnel = FALSE,
    sunsetFunnel = FALSE,
    funnelPlotMode = "posOff",
    funnelPlotWidth = 600,
    funnelPlotHeight = 500,
    infDiagPlotShow = FALSE,
    infQQPlotShow = FALSE,
    lhPlotShow = FALSE,
    tostLower = -0.1,
    tostUpper = 0.1,
    tostAlpha = 0.05,
    showTost = FALSE,
    tostPlotShow = FALSE,
    scatterPlotShow = FALSE,
    scatterPlotLegend = TRUE,
    scatterPlotLabel = FALSE,
    scatterPlotGrid = FALSE,
    scatterPlotPI = FALSE,
    scatterPlotCI = FALSE,
    scatterPlotScale = FALSE,
    radialPlotShow = FALSE,
    radialPlotCenter = FALSE,
    radialPlotTransf = "none",
    radialPlotSteps = 7,
    baujatPlotShow = FALSE,
    baujatPlotSymbol = "ids",
    baujatPlotGrid = TRUE,
    goshPlotShow = FALSE,
    goshPlotHet = "I2",
    goshPlotSubsets = 1000,
    goshPlotOut = 0,
    leave1outPlotMode = "posOff",
    leave1outPlotShow = FALSE,
    leave1outTableShow = FALSE,
    leave1outPrediction = FALSE,
    leave1outShade = TRUE,
    leave1outMode = "posOff",
    leave1outGroupOrder = FALSE,
    leave1outOrder = "none",
    distabPBA = FALSE,
    showTes = FALSE,
    pcurvePlotShow = FALSE,
    fsntype = "Rosenthal",
    tesAlternative = "greater",
    tesH0 = 0,
    tesTest = "chi2",
    tesAlpha = 0.05,
    showSelmodel = FALSE,
    selModelType = "halfnorm",
    showPuniform = FALSE,
    alphaPunif = 0.05,
    methodPunif = "P",
    puniformSide = "right",
    jlogMode = "posOff",
    cumulativeTableShow = FALSE,
    cumulativePlotMode = "posOff",
    cumulativeOrder = "original",
    cumulativeGroupOrder = FALSE,
    cumulativeDirection = "asc",
    cumulativeSortVariable,
    cumulativePrediction = FALSE,
    cumulativeShade = FALSE,
    predProbTableShow = FALSE,
    predProbPlotShow = FALSE,
    predProbThreshold = 0,
    predProbDirection = "below") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("mzEffectSizes requires jmvcore to be installed (restart may be required)")

    if ( ! missing(slab)) slab <- jmvcore::resolveQuo(jmvcore::enquo(slab))
    if ( ! missing(yi)) yi <- jmvcore::resolveQuo(jmvcore::enquo(yi))
    if ( ! missing(vi)) vi <- jmvcore::resolveQuo(jmvcore::enquo(vi))
    if ( ! missing(ciLower)) ciLower <- jmvcore::resolveQuo(jmvcore::enquo(ciLower))
    if ( ! missing(ciUpper)) ciUpper <- jmvcore::resolveQuo(jmvcore::enquo(ciUpper))
    if ( ! missing(subgroup)) subgroup <- jmvcore::resolveQuo(jmvcore::enquo(subgroup))
    if ( ! missing(moderator)) moderator <- jmvcore::resolveQuo(jmvcore::enquo(moderator))
    if ( ! missing(robDomains)) robDomains <- jmvcore::resolveQuo(jmvcore::enquo(robDomains))
    if ( ! missing(cumulativeSortVariable)) cumulativeSortVariable <- jmvcore::resolveQuo(jmvcore::enquo(cumulativeSortVariable))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(slab), slab, NULL),
            `if`( ! missing(yi), yi, NULL),
            `if`( ! missing(vi), vi, NULL),
            `if`( ! missing(ciLower), ciLower, NULL),
            `if`( ! missing(ciUpper), ciUpper, NULL),
            `if`( ! missing(subgroup), subgroup, NULL),
            `if`( ! missing(moderator), moderator, NULL),
            `if`( ! missing(robDomains), robDomains, NULL),
            `if`( ! missing(cumulativeSortVariable), cumulativeSortVariable, NULL))

    for (v in subgroup) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in robDomains) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- mzEffectSizesOptions$new(
        d3ExportForest = d3ExportForest,
        d3ExportFunnel = d3ExportFunnel,
        d3ExportLeave1Out = d3ExportLeave1Out,
        d3ExportCumulative = d3ExportCumulative,
        slab = slab,
        yi = yi,
        vi = vi,
        ciLower = ciLower,
        ciUpper = ciUpper,
        inputCiLevel = inputCiLevel,
        subgroup = subgroup,
        moderator = moderator,
        robDomains = robDomains,
        tabbedControl = tabbedControl,
        tabbedControlModelType = tabbedControlModelType,
        modelest = modelest,
        testType = testType,
        level = level,
        modelmea = modelmea,
        meaType = meaType,
        showBackTransform = showBackTransform,
        showHetTest = showHetTest,
        hetTestBoot = hetTestBoot,
        showHEC = showHEC,
        showModelFit = showModelFit,
        showTextRepo = showTextRepo,
        addfit = addfit,
        addpred = addpred,
        forestPredictionStyle = forestPredictionStyle,
        showweights = showweights,
        shadeRows = shadeRows,
        pchForest = pchForest,
        mainTitle = mainTitle,
        forestOrder = forestOrder,
        xAxisTitle = xAxisTitle,
        ordSubgr = ordSubgr,
        steps = steps,
        forestPlotMode = forestPlotMode,
        forestPlotWidth = forestPlotWidth,
        forestPlotHeight = forestPlotHeight,
        forestTableShow = forestTableShow,
        forestRobShow = forestRobShow,
        yaxis = yaxis,
        yaxisInv = yaxisInv,
        enhanceFunnel = enhanceFunnel,
        sunsetFunnel = sunsetFunnel,
        funnelPlotMode = funnelPlotMode,
        funnelPlotWidth = funnelPlotWidth,
        funnelPlotHeight = funnelPlotHeight,
        infDiagPlotShow = infDiagPlotShow,
        infQQPlotShow = infQQPlotShow,
        lhPlotShow = lhPlotShow,
        tostLower = tostLower,
        tostUpper = tostUpper,
        tostAlpha = tostAlpha,
        showTost = showTost,
        tostPlotShow = tostPlotShow,
        scatterPlotShow = scatterPlotShow,
        scatterPlotLegend = scatterPlotLegend,
        scatterPlotLabel = scatterPlotLabel,
        scatterPlotGrid = scatterPlotGrid,
        scatterPlotPI = scatterPlotPI,
        scatterPlotCI = scatterPlotCI,
        scatterPlotScale = scatterPlotScale,
        radialPlotShow = radialPlotShow,
        radialPlotCenter = radialPlotCenter,
        radialPlotTransf = radialPlotTransf,
        radialPlotSteps = radialPlotSteps,
        baujatPlotShow = baujatPlotShow,
        baujatPlotSymbol = baujatPlotSymbol,
        baujatPlotGrid = baujatPlotGrid,
        goshPlotShow = goshPlotShow,
        goshPlotHet = goshPlotHet,
        goshPlotSubsets = goshPlotSubsets,
        goshPlotOut = goshPlotOut,
        leave1outPlotMode = leave1outPlotMode,
        leave1outPlotShow = leave1outPlotShow,
        leave1outTableShow = leave1outTableShow,
        leave1outPrediction = leave1outPrediction,
        leave1outShade = leave1outShade,
        leave1outMode = leave1outMode,
        leave1outGroupOrder = leave1outGroupOrder,
        leave1outOrder = leave1outOrder,
        distabPBA = distabPBA,
        showTes = showTes,
        pcurvePlotShow = pcurvePlotShow,
        fsntype = fsntype,
        tesAlternative = tesAlternative,
        tesH0 = tesH0,
        tesTest = tesTest,
        tesAlpha = tesAlpha,
        showSelmodel = showSelmodel,
        selModelType = selModelType,
        showPuniform = showPuniform,
        alphaPunif = alphaPunif,
        methodPunif = methodPunif,
        puniformSide = puniformSide,
        jlogMode = jlogMode,
        cumulativeTableShow = cumulativeTableShow,
        cumulativePlotMode = cumulativePlotMode,
        cumulativeOrder = cumulativeOrder,
        cumulativeGroupOrder = cumulativeGroupOrder,
        cumulativeDirection = cumulativeDirection,
        cumulativeSortVariable = cumulativeSortVariable,
        cumulativePrediction = cumulativePrediction,
        cumulativeShade = cumulativeShade,
        predProbTableShow = predProbTableShow,
        predProbPlotShow = predProbPlotShow,
        predProbThreshold = predProbThreshold,
        predProbDirection = predProbDirection)

    analysis <- mzEffectSizesClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

